use snacka::opus::{Application,Bandwidth,Decoder,Encoder,EncoderConfig,FrameDuration,Mode,RateControl};
fn main(){let out=std::env::args().nth(1).unwrap();std::fs::create_dir_all(&out).unwrap();for wide in [false,true]{let(samples,rate,bw,duration,label) = if wide{(960,6000,Bandwidth::Wideband,FrameDuration::Ms20,"wb")}else{(480,12000,Bandwidth::Narrowband,FrameDuration::Ms10,"nb")};let values:Vec<f32>=if wide{std::fs::read("/tmp/snacka-opus-goal-speech-diagnostics-20261015/cen2-fjam-b.input.f32").unwrap().chunks_exact(4).map(|b|f32::from_le_bytes(b.try_into().unwrap())).collect()}else{(0..96*480).map(|n|match(n/24+n/480)%8{0|1=>1.0,2|3=>-1.0,4=>f32::from_bits(0x3f7fffff),5=>-f32::from_bits(0x3f7fffff),6=>0.0,_=>-0.0}).collect()};let config=EncoderConfig::new(rate,1,duration,bw,Application::Voice).unwrap().with_mode(Mode::Silk).unwrap().with_rate_control(RateControl::Constant);let mut enc=Encoder::new(config).unwrap();let mut dec=Decoder::new(1).unwrap();let mut packet=[0xa5;15];let mut pcm=vec![0.0;samples];let mut records=Vec::new();let mut rendered=Vec::new();let mut ranges=Vec::new();let mut active=0;let mut failed=None;let mut accepted=0;for(index,input)in values.chunks_exact(samples).enumerate(){match enc.encode(input,&mut packet){Ok(n)=>{ranges.extend_from_slice(&enc.final_range().to_le_bytes());let parsed=snacka::opus::Packet::parse(&packet[..n]).unwrap();let payload=parsed.frames().next().unwrap();let mut entropy=snacka::entropy::Decoder::new(payload);let header=snacka::opus::silk::Header::decode(&mut entropy,if wide{snacka::opus::silk::PacketDuration::Ms20}else{snacka::opus::silk::PacketDuration::Ms10},1).unwrap();active+=usize::from(header.voice_activity(0,0).unwrap());records.extend_from_slice(&(n as u32).to_le_bytes());records.extend_from_slice(&packet[..n]);assert_eq!(dec.decode(&packet[..n],&mut pcm).unwrap(),samples);assert_eq!(enc.final_range(),dec.final_range());for v in &pcm{rendered.extend_from_slice(&v.to_le_bytes());}accepted+=1;},Err(e)=>{failed=Some((index,e));break;}}}std::fs::write(format!("{out}/{label}.ranges"),ranges).unwrap();std::fs::write(format!("{out}/{label}.packets"),records).unwrap();std::fs::write(format!("{out}/{label}.owned.f32"),rendered).unwrap();std::fs::write(format!("{out}/{label}.input.f32"),values.iter().flat_map(|v|v.to_le_bytes()).collect::<Vec<_>>()).unwrap();println!("{label} accepted={accepted} active={active} failed={failed:?}");}}
